void AtomSolver::InitLib() {
	for (int i = 0; i < 24; i++) {
		for (int j = 0; j < 3; j++) {
			for (int k = 0; k < 18; k++) {
				for (int l = 0; l < 16; l++) {
					AtomLib[i][j][k][l].init();
				}
			}
		}
	}
	InitLib_FR();
	InitLib_FU();
	InitLib_FL();
	InitLib_FD();
	InitLib_RF();
	InitLib_RU();
	InitLib_RB();
	InitLib_RD();
	InitLib_UF();
	InitLib_UR();
	InitLib_UB();
	InitLib_UL();
	InitLib_BR();
	InitLib_BU();
	InitLib_BL();
	InitLib_BD();
	InitLib_LF();
	InitLib_LU();
	InitLib_LB();
	InitLib_LD();
	InitLib_DF();
	InitLib_DR();
	InitLib_DB();
	InitLib_DL();
}

